import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, terms: string, dueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const effectiveTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, effectiveTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier];

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    const effectiveDiscount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (effectiveDiscount > 0) {
      enrichedLine.discountPercent = effectiveDiscount;
    }
    enrichedLines.push(enrichedLine);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms: effectiveTerms,
    dueDate,
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single invoice line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  return Math.max(0, roundCents(lineTotal(line) * line.discountPercent / 100));
}

/**
 * Calculate the VAT for a single invoice line (on the amount after discount).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return Math.max(0, roundCents(amountAfterDiscount * line.vatRate / 100));
}

